// ── 附录：数值校验表（生成器实算，供人工抽查）──
// 政治系：L1 造价 52~120 铁当量；维护费 3~18 星币/分钟；需人口 6~40。
// 深空系：L1 造价 190~355 铁当量；维护费 6~24 星币/分钟；需人口 10~60。
// 生态系：L1 造价 40~190 铁当量；维护费 2~20 星币/分钟；需人口 4~30。
// 军事系：L1 造价 62~364 铁当量；维护费 3~24 星币/分钟；需人口 6~45。
// ── 附录：分类小计 ──
// 政治系 10 种：L1 均价 81 铁当量；全部升满级共 7682 铁当量。
// 深空系 10 种：L1 均价 249 铁当量；全部升满级共 20618 铁当量。
// 生态系 15 种：L1 均价 74 铁当量；全部升满级共 10403 铁当量。
// 军事系 15 种：L1 均价 146 铁当量；全部升满级共 18898 铁当量。

// ── 自检：BuildingsV30SelfTest() ──────────────────────────────────
// 在浏览器控制台调用：BuildingsV30SelfTest()（需先调用 mergeBuildingsV30()）。
// 在 node 里调用：先 global.BUILDINGS = {} 再 mergeBuildingsV30()，然后自检。
// 只读校验，不写任何状态。校验项：
//   1. BUILD_ORDER_V30 共 50 个 id，全部带 v30_ 前缀且唯一；
//   2. 每个建筑已并入 BUILDINGS，levels[0] 为 null，L1~L3 齐全；
//   3. 每级 cost 非空、needPop >= 0、upkeep.credits > 0；
//   4. 每级至少一个效果键（produce/convert/数值效果，排除 cost/needPop/
//      needTech/power/powerUse/upkeep/desc 等非效果键）；
//   5. 造价递增带：L2/L1 与 L3/L2 均在 2.0×~3.0× 内（铁 1 / 钢 2.5 /
//      稀有 5 / 冰 1 / 科技点 8 折算）。
function BuildingsV30SelfTest() {
  const EQ = { iron: 1, steel: 2.5, rare: 5, ice: 1, tech: 8, water: 1, food: 1 };
  const eq = (c) => Object.keys(c).reduce((s, k) => s + (EQ[k] || 1) * c[k], 0);
  const NON_EFFECT = { cost: 1, needPop: 1, needTech: 1, needCommand: 1, power: 1,
    powerUse: 1, upkeep: 1, desc: 1 };
  const errs = [];
  const ok = (cond, msg) => { if (!cond) errs.push(msg); };
  ok(Array.isArray(BUILD_ORDER_V30) && BUILD_ORDER_V30.length === 50,
     'BUILD_ORDER_V30 不是 50 项：' + (BUILD_ORDER_V30 && BUILD_ORDER_V30.length));
  ok(new Set(BUILD_ORDER_V30).size === 50, 'BUILD_ORDER_V30 有重复 id');
  ok(BUILD_ORDER_V30.every((id) => id.indexOf('v30_') === 0), '有 id 缺 v30_ 前缀');
  if (typeof BUILDINGS === 'undefined') {
    errs.push('全局 BUILDINGS 不存在（浏览器里先加载 build.js 再调用 mergeBuildingsV30()）');
    return { pass: false, errors: errs, buildings: 0, levels: 0 };
  }
  for (const bid of BUILD_ORDER_V30) {
    const b = BUILDINGS[bid];
    ok(!!b, '未并入 BUILDINGS：' + bid);
    if (!b) continue;
    ok(Array.isArray(b.levels) && b.levels[0] === null && b.levels.length === 4,
       bid + ' levels 结构不是 [null, L1, L2, L3]');
    if (!Array.isArray(b.levels) || b.levels.length !== 4) continue;
    const es = [1, 2, 3].map((i) => eq(b.levels[i].cost || {}));
    ok(es[1] / es[0] >= 2.0 && es[1] / es[0] <= 3.0,
       bid + ' L2/L1 不在 2.0~3.0×：' + (es[1] / es[0]).toFixed(2));
    ok(es[2] / es[1] >= 2.0 && es[2] / es[1] <= 3.0,
       bid + ' L3/L2 不在 2.0~3.0×：' + (es[2] / es[1]).toFixed(2));
    for (let i = 1; i <= 3; i++) {
      const lv = b.levels[i];
      ok(lv.cost && Object.keys(lv.cost).length > 0, bid + ' L' + i + ' cost 为空');
      ok(typeof lv.needPop === 'number' && lv.needPop >= 0, bid + ' L' + i + ' needPop 非法');
      ok(lv.upkeep && lv.upkeep.credits > 0, bid + ' L' + i + ' upkeep <= 0');
      const effKeys = Object.keys(lv).filter((k) => !NON_EFFECT[k]);
      ok(effKeys.length > 0, bid + ' L' + i + ' 无效果键');
    }
  }
  return { pass: errs.length === 0, errors: errs,
           buildings: BUILD_ORDER_V30.length, levels: BUILD_ORDER_V30.length * 3 };
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { BUILD_ORDER_V30, mergeBuildingsV30, BuildingsV30SelfTest };
}
